package com.doudou.wxq;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;import java.text.SimpleDateFormat;import java.util.*;
/** Local, authorized component port. Every executable resource comes from the APK. */
final class WorkshopView extends LinearLayout implements Repository.Listener {
 private final Activity activity;private final String module;private final Repository repo;private final FrameLayout stage;private final TextView status;private final ProgressBar progress;
 private LocalWorkshop bundle;private WebView web;private View error;private boolean disposed=false,rendererGone=false;private String dataBuild="";
 WorkshopView(Activity a,String id,Runnable navigation,Runnable home){super(a);activity=a;module=id;repo=Repository.get(a);setOrientation(VERTICAL);setBackgroundColor(0xff101724);LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(6),dp(4),dp(6),dp(4));bar.setBackgroundColor(0xff162630);bar.addView(button("☰","打开功能侧边栏",navigation),new LayoutParams(dp(40),dp(40)));LinearLayout caption=new LinearLayout(a);caption.setOrientation(VERTICAL);TextView title=text(SiteModules.title(id),16,0xffedf5f1);status=text("正在准备工作室",10,0xff92b2b6);caption.addView(title);caption.addView(status);bar.addView(caption,new LayoutParams(0,-2,1));if(SiteModules.SIMULATOR.equals(id)){Button plans=button("方案","本地保存、导入和导出",()->{});plans.setTextSize(13);plans.setOnClickListener(v->plans(v));bar.addView(plans,new LayoutParams(dp(45),dp(40)));}bar.addView(button("↻","同步资料并刷新",()->{repo.checkUpdates();reload();}),new LayoutParams(dp(38),dp(40)));bar.addView(button("‹","返回阵容推荐",home),new LayoutParams(dp(38),dp(40)));addView(bar);progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);addView(progress,new LayoutParams(-1,dp(2)));stage=new FrameLayout(a);addView(stage,new LayoutParams(-1,0,1));repo.add(this);create();}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private TextView text(String s,int size,int color){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}private Button button(String s,String desc,Runnable action){Button b=new Button(activity);b.setText(s);b.setTextSize(20);b.setTextColor(0xffa2e8d0);b.setBackgroundColor(Color.TRANSPARENT);b.setContentDescription(desc);b.setPadding(0,0,0,0);b.setMinWidth(0);b.setMinimumWidth(0);b.setOnClickListener(v->action.run());return b;}
 private String key(){return "workshop_draft_"+module;}
 private void create(){if(disposed)return;try{bundle=LocalWorkshop.get(activity);dataBuild=bundle.data().optString("sourceBuild");rendererGone=false;web=new WebView(activity);web.setBackgroundColor(0xff0b0f18);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setUseWideViewPort(true);s.setLoadWithOverviewMode(true);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);
  web.setWebChromeClient(new WebChromeClient(){public void onProgressChanged(WebView v,int p){if(v!=web||disposed)return;progress.setProgress(p);progress.setVisibility(p==100?View.GONE:View.VISIBLE);}public boolean onJsPrompt(WebView v,String url,String message,String value,JsPromptResult result){if(SiteModules.allowed(url)&&"__WXQ_EXPORT_PNG__".equals(message)){try{LocalPngExporter.save(activity,value);result.confirm("ok");toast("阵容图已保存到图片目录");}catch(Exception e){result.confirm("error");toast("图片保存失败："+e.getMessage());}return true;}return false;}});
  web.setWebViewClient(new WebViewClient(){
   public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if(!r.isForMainFrame())return false;if(SiteModules.allowed(r.getUrl().toString()))return false;toast("该功能已改用工具栏的本地方案操作");return true;}
   public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();try{if(LocalWorkshop.HOST.equals(u.getHost()))return bundle.resource(u.getPath());if("GET".equals(r.getMethod())&&"static.datatft.com".equals(u.getHost())&&ImageDiskCache.accepts(u.toString())){WebResourceResponse built=bundle.image(u.toString());if(built!=null)return built;ImageDiskCache.Entry e=repo.images.get(u.toString());Map<String,String> h=new HashMap<>();h.put("Access-Control-Allow-Origin","*");h.put("Cache-Control","no-store");return new WebResourceResponse(e.mime,null,200,"OK",h,new java.io.ByteArrayInputStream(e.bytes));}}catch(Exception ignored){}return LocalWorkshop.blocked();}
   public void onPageStarted(WebView v,String url,android.graphics.Bitmap b){if(error!=null)error.setVisibility(View.GONE);status.setText("正在打开…");}
   public void onPageFinished(WebView v,String url){if(disposed||v!=web)return;persist();status.setText("基础资料可离线使用");progress.setVisibility(View.GONE);}
   public void doUpdateVisitedHistory(WebView v,String url,boolean reload){if(v==web)persist();}
   public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())failure("本地模块未能打开，点击重试。");}
   public boolean onRenderProcessGone(WebView v,RenderProcessGoneDetail d){if(v!=web)return true;rendererGone=true;release();failure("显示进程已重置，已保留本地方案，点击重试。");return true;}
  });
  stage.addView(web,new FrameLayout.LayoutParams(-1,-1));String url=repo.prefs.getString(key(),SiteModules.url(module));web.loadUrl(SiteModules.allowed(url)?url:SiteModules.url(module));
 }catch(Exception e){release();failure("本地模块准备失败："+e.getMessage());}}
 void persist(){try{if(web!=null){String url=web.getUrl();if(SiteModules.allowed(url)&&url.length()<100000)repo.prefs.edit().putString(key(),url).apply();}}catch(RuntimeException ignored){}}
 private void reload(){persist();if(error!=null)error.setVisibility(View.GONE);if(web==null)create();else{try{dataBuild=bundle.data().optString("sourceBuild");}catch(Exception ignored){}web.reload();}}
 @Override public void onEvent(JSONObject e){if(disposed)return;if("catalog".equals(e.optString("type"))){JSONObject c=e.optJSONObject("catalog");if(c!=null&&!c.optString("sourceBuild").equals(dataBuild))reload();}else if("dataStatus".equals(e.optString("type"))&&"failed".equals(e.optString("state")))status.setText("资料检查失败 · 仍可使用本地资料");}
 private void failure(String msg){if(disposed)return;progress.setVisibility(View.GONE);status.setText("本地模块未就绪");if(error!=null)stage.removeView(error);LinearLayout p=new LinearLayout(activity);p.setOrientation(VERTICAL);p.setGravity(Gravity.CENTER);p.setPadding(dp(20),dp(20),dp(20),dp(20));p.setBackgroundColor(0xff101724);TextView t=text(msg,13,0xffb5cbd0);t.setGravity(Gravity.CENTER);p.addView(t);Button retry=new Button(activity);retry.setText("重新打开");retry.setOnClickListener(v->reload());p.addView(retry);error=p;stage.addView(p,new FrameLayout.LayoutParams(-1,-1));}
 private String currentCode()throws Exception{if(web==null)throw new IllegalArgumentException("请先打开模拟器");String url=web.getUrl();String value=url==null?null:Uri.parse(url).getQueryParameter("lineup");if(value==null)throw new IllegalArgumentException("先在棋盘添加英雄，再保存方案");return LocalPlan.code(value);}
 private void plans(View anchor){PopupMenu p=new PopupMenu(activity,anchor);for(String label:new String[]{"保存当前方案","打开已保存方案","复制软件方案码","导入软件方案码","保存阵容图","保存横向图"})p.getMenu().add(label);p.setOnMenuItemClickListener(item->{String t=item.getTitle().toString();try{if(t.equals("保存当前方案"))savePlan(currentCode());else if(t.equals("打开已保存方案"))openPlans();else if(t.equals("复制软件方案码")){((android.content.ClipboardManager)activity.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("万象弈伴软件方案码",currentCode()));toast("方案码已复制（不是游戏导入码）");}else if(t.equals("导入软件方案码"))importPlan();else if(web!=null)web.evaluateJavascript("window.WxqLocalPort&&WxqLocalPort.exportImage("+t.equals("保存横向图")+")",null);}catch(Exception e){toast(e.getMessage());}return true;});p.show();}
 private JSONArray saved(){try{return new JSONArray(repo.prefs.getString("workshop_saved_plans","[]"));}catch(Exception e){return new JSONArray();}}
 private void savePlan(String code){EditText name=new EditText(activity);name.setSingleLine(true);name.setText("阵容方案 "+new SimpleDateFormat("MM-dd HH:mm",Locale.CHINA).format(new Date()));new AlertDialog.Builder(activity).setTitle("保存到本机").setView(name).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{try{JSONArray list=saved(),next=new JSONArray();next.put(new JSONObject().put("name",name.getText().toString().trim().isEmpty()?"未命名方案":name.getText().toString().trim().substring(0,Math.min(40,name.getText().toString().trim().length()))).put("code",code));for(int i=0;i<Math.min(11,list.length());i++)next.put(list.get(i));repo.prefs.edit().putString("workshop_saved_plans",next.toString()).apply();toast("方案已保存到本机");}catch(Exception e){toast("保存未完成，请重试");}}).show();}
 private void openPlans(){JSONArray list=saved();if(list.length()==0){toast("还没有保存方案");return;}String[] names=new String[list.length()];for(int i=0;i<list.length();i++)names[i]=list.optJSONObject(i).optString("name");new AlertDialog.Builder(activity).setTitle("本机方案（最近 12 个）").setItems(names,(d,i)->{try{web.loadUrl(LocalPlan.url(list.getJSONObject(i).getString("code")));}catch(Exception e){toast("方案未能打开");}}).setNegativeButton("返回",null).show();}
 private void importPlan(){EditText input=new EditText(activity);input.setHint("粘贴 WXQ1: 软件方案码或原站带 lineup 的方案链接");input.setMinLines(3);input.setMaxLines(6);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("导入软件方案（非游戏阵容码）").setView(input).setNegativeButton("取消",null).setPositiveButton("导入",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String url=LocalPlan.url(input.getText().toString());web.loadUrl(url);dialog.dismiss();}catch(Exception e){input.setError(e.getMessage());}}));dialog.show();}
 private void toast(String s){Toast.makeText(activity,s==null?"操作未完成":s,Toast.LENGTH_LONG).show();}
 boolean back(){if(web!=null){web.evaluateJavascript("document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))",null);if(web.canGoBack()){web.goBack();return true;}}return false;}
 private void release(){if(web!=null){persist();WebView old=web;web=null;stage.removeView(old);try{if(!rendererGone)old.stopLoading();old.destroy();}catch(RuntimeException ignored){}}}
 void dispose(){disposed=true;repo.remove(this);release();}
}
